/* From Uiverse.io by JaydipPrajapati1910 - Tags: animation, loading, loader, animated, circle loader, loader circle */
.__UIV_SCOPE__ .spinner {
  position: absolute;
  width: 128px;
  height: 128px;
  top: calc(50% - 64px);
  left: calc(50% - 64px);
  transform: perspective(206px) rotateX(45deg);
}

.__UIV_SCOPE__ .outer {
  box-sizing: border-box;
  animation: spin 3s linear infinite;
  height: 100%;
}

.__UIV_SCOPE__ .inner {
  position: absolute;
  border-radius: 50%;
  width: 64px;
  height: 64px;
}

.__UIV_SCOPE__ .tl {
  top: 0;
  left: 0;
  border-top: 8px solid red;
  border-left: 10px solid red;
  animation: spin 1s ease-in-out infinite;
}

.__UIV_SCOPE__ .tr {
  top: 0;
  right: 0;
  border-top: 8px solid #0575E6;
  border-right: 10px solid #0575E6;
  animation: spin 1s ease-in-out infinite;
}

.__UIV_SCOPE__ .br {
  bottom: 0;
  right: 0;
  border-bottom: 8px solid  #00F260;
  border-right: 10px solid  #00F260;
  animation: spin 1s ease-in-out infinite;
}

.__UIV_SCOPE__ .bl {
  bottom: 0;
  left: 0;
  border-bottom: 8px solid  #e9e93e;
  border-left: 10x solid #e9e93e;
  animation: spin 1s ease-in-out infinite;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}
